4376: # engine): RESOURCE_EXHAUSTED -> quota, UNAUTHENTICATED / PERMISSION_DENIED / "not signed
4377: # in" -> auth, INVALID_ARGUMENT / "invalid model selection" -> capability, UNAVAILABLE /
4378: # DEADLINE_EXCEEDED -> transport.
4379: # A usage limit said in WORDS ($script:QuotaTextPattern: usage limit, quota, rate limit, ...)
