524: # the fingerprint. A submodule or nested repository is recorded as 'dir' and not
525: # recursed. Every omission is spelled out in fingerprint_note. No git -> tree_sha256
526: # '' and fingerprint_note 'no git'. changed_files and dirty count the manifest
527: # entries, i.e. also without the collaboration directory.
528: # git status runs with --no-optional-locks, so computing a fingerprint never writes
529: # to the repository (not even an index refresh) - -DryRun stays write-free.
530: function Get-RevisionInfo {
531:     param([string]$Root, [string]$CollabRoot = '')
532:     $info = [pscustomobject]@{
533:         base_commit       = 'unknown'
534:         short_sha         = 'unknown'
535:         dirty             = $false
536:         reviewed_revision = 'unknown'
537:         tree_sha256       = ''
538:         changed_files     = 0
539:         fingerprint_note  = 'no git'
540:         manifest          = ''
