565:     # Parse the NUL-separated entries: "XY <path>", and for a rename or copy the
566:     # source path follows as the next NUL-terminated field.
567:     $tokens = $script:Utf8NoBom.GetString($status.Bytes).Split([char]0)
568:     $entries = New-Object System.Collections.Generic.List[object]
569:     $excluded = 0
570:     $i = 0
571:     while ($i -lt $tokens.Length) {
572:         $tok = $tokens[$i]
573:         $i++
574:         if ($tok.Length -lt 4) { continue }
575:         $xy = $tok.Substring(0, 2)
576:         $path = $tok.Substring(3)
577:         $orig = $null
578:         if ($xy[0] -ceq 'R' -or $xy[0] -ceq 'C' -or $xy[1] -ceq 'R' -or $xy[1] -ceq 'C') {
579:             if ($i -lt $tokens.Length) { $orig = $tokens[$i]; $i++ }
580:         }
581:         if ($collabRel -and ($path.Equals($collabRel, $cmp) -or $path.StartsWith($collabRel + '/', $cmp))) {
