631:     $notes.Add('ignored files excluded')
632:     $notes.Add('untracked file modes not recorded')
633:     if ($dirs -gt 0) { $notes.Add("submodules not recursed ($dirs directory entries)") }
634:     else { $notes.Add('submodules not recursed') }
635:     if ($unreadable -gt 0) { $notes.Add("$unreadable files unreadable") }
