332: # -Range (wave 24, T1): `git diff --shortstat <range> --` once, in the repository root - "the
333: # range changes N files, M lines" (M = insertions + deletions). { Range; Files; Insertions;
334: # Deletions; Lines; Error ('' or why the range is refused: not a revision range git knows here,
335: # an argument that could be read as an option, a single revision, git not runnable) }.
336: # (wave 24b, F08-8) Only a range of two revisions - base..head or base...head, both named - is
337: # measured: `git diff <revision>` would measure the WORKING TREE against that revision, a size
338: # that changes while the review runs and differs from what the reviewer reads.
339: function Get-RangeStat {
340:     param([string]$Root, [string]$Range)
341:     $r = [pscustomobject]@{ Range = $Range; Files = 0; Insertions = 0; Deletions = 0; Lines = 0; Error = '' }
342:     if (-not $Range -or $Range.StartsWith('-') -or $Range -match '[\s\x00-\x1f]') {
343:         $r.Error = "-Range '$Range' is not a git revision range (e.g. a1b2c3d..HEAD; no spaces, not starting with '-')"
344:         return $r
345:     }
346:     $m = [regex]::Match($Range, '^(?<base>.+?)(?<sep>\.\.\.?)(?<head>.+)$')
347:     if (-not $m.Success -or $m.Groups['head'].Value.Contains('..') -or $m.Groups['head'].Value.StartsWith('.')) {
348:         $r.Error = "-Range '$Range' is not a range of two revisions: pass base..head or base...head (e.g. a1b2c3d..HEAD) - a single revision would measure the working tree against it, which changes while the review runs"
349:         return $r
350:     }
351:     $cap = Invoke-GitCapture -Root $Root -GitArgs @('diff', '--shortstat', $Range, '--')
352:     if ($null -eq $cap) { $r.Error = "-Range '$Range': git could not be started in $Root"; return $r }
353:     if ($cap.ExitCode -ne 0) {
354:         $why = @(([string]$cap.Err) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ }) | Select-Object -First 1
355:         $r.Error = "-Range '$Range' is not a revision range git knows in $Root (git diff --shortstat: $(if ($why) { $why } else { "exit $($cap.ExitCode)" }))"
356:         return $r
357:     }
358:     $out = $script:Utf8NoBom.GetString($cap.Bytes)
359:     if ($out -match '(\d+) files? changed') { $r.Files = [int]$Matches[1] }
360:     if ($out -match '(\d+) insertions?\(\+\)') { $r.Insertions = [int]$Matches[1] }
361:     if ($out -match '(\d+) deletions?\(-\)') { $r.Deletions = [int]$Matches[1] }
362:     $r.Lines = $r.Insertions + $r.Deletions
363:     return $r
364: }
